import sys

def test_pydantic_v1_warning():
    print("Testing Pydantic v1 warning...")
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter("always")

        try:
            from fastapi._compat import v1
            print("Imported fastapi._compat.v1")
        except ImportError as e:
            print(f"Failed to import fastapi._compat.v1: {e}")
            sys.exit(1)

        found = False
        for warning in w:
            if "Pydantic v1 is deprecated" in str(warning.message):
                found = True
                print(f"Found warning: {warning.message}")
                break

        if not found:
            print("Warning NOT found!")
            sys.exit(1)
        else:
            print("Warning found successfully!")

if __name__ == "__main__":
    test_pydantic_v1_warning()

import warnings
import sys

def test_pydantic_v1_warning():
    print("Testing Pydantic v1 warning...")

    # Clear sys.modules to ensure we trigger the import
    if 'fastapi._compat.v1' in sys.modules:
        del sys.modules['fastapi._compat.v1']

    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter("always")

        from pydantic.v1 import BaseModel
        from fastapi import FastAPI
        from fastapi.testclient import TestClient

        app = FastAPI()

        class User(BaseModel):
            name: str

        @app.get("/")
        def read_root(user: User = None):
            return {"Hello": "World"}

        client = TestClient(app)
        client.get("/")

        found = False
        for warning in w:
            if "Pydantic v1 is deprecated" in str(warning.message):
                found = True
                print(f"Found warning: {warning.message}")
                break

        if not found:
            print("Warning NOT found!")
            sys.exit(1)
        else:
            print("Warning found successfully!")

if __name__ == "__main__":
    test_pydantic_v1_warning()

